INSERT INTO project_supervisors (project_id, lecturer_id, supervisor_type) SELECT p.id, l.id, 'MAIN'::supervisor_type FROM projects p JOIN lecturers l ON l.lecturer_code = 'TruongLV11' WHERE p.semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND p.code = 'FA25SE224' ON CONFLICT (project_id, lecturer_id) DO UPDATE SET supervisor_type = EXCLUDED.supervisor_type;
