INSERT INTO round_days (round_id, day_date) VALUES ((SELECT id FROM rounds WHERE semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND type = 'REVIEW_1'::round_type), '2026-01-22') ON CONFLICT (round_id, day_date) DO NOTHING;
INSERT INTO timeslots (round_day_id, start_at, end_at) SELECT rd.id, '2026-01-22T09:00:00+07:00'::timestamptz, '2026-01-22T09:30:00+07:00'::timestamptz FROM round_days rd WHERE rd.round_id = (SELECT id FROM rounds WHERE semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND type = 'REVIEW_1'::round_type) AND rd.day_date = '2026-01-22' ON CONFLICT (round_day_id, start_at, end_at) DO NOTHING;
INSERT INTO round_room_types (round_id, room_type) SELECT (SELECT id FROM rounds WHERE semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND type = 'REVIEW_1'::round_type), room_type FROM rooms WHERE code = 'NVH G.02' ON CONFLICT DO NOTHING;
INSERT INTO round_groups (round_id, group_id) SELECT (SELECT id FROM rounds WHERE semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND type = 'REVIEW_1'::round_type), g.id FROM groups g JOIN projects p ON p.id = g.project_id WHERE p.semester_id = (SELECT id FROM semesters WHERE code = 'SE-2026-2027') AND p.code = 'FA25SE224' ON CONFLICT DO NOTHING;
